sys_script_include.script:
var CertificateRenewalTaskUtil = Class.create();
CertificateRenewalTaskUtil.prototype = {
    initialize: function() {},
    renewCertificate: function(certificateSysId, certMeta, openedThrough) {
        return this.triggerRenewal(certificateSysId, certMeta, null, openedThrough);
    },
    renewCertificateWithAttrs: function(certificateSysId, subjectCommonAttrs, openedThrough) {
        return this.triggerRenewal(certificateSysId, null, subjectCommonAttrs, openedThrough);
    },
    renewCertificates: function(certificateSysIdList, openedThrough) {
        if (certificateSysIdList && !certificateSysIdList.length) {
            return [{
                "error": gs.getMessage("Certificate List is empty.")
            }];
        }
        var retArr = [];
        certificateSysIdList.forEach(function(certificateSysId) {
            var resp = this.triggerRenewal(certificateSysId, null, null, openedThrough);
            retArr.push(resp);
        }, this);
        return retArr;
    },

	renewCertificatesAsync: function(certificateSysIdList, openedThrough) {
		if (certificateSysIdList && !certificateSysIdList.length) {
            return [{
                "error": gs.getMessage("Certificate List is empty.")
            }];
        }

		var length = certificateSysIdList.length;
		var triggerId = gs.generateGUID();
		// Upper limit for event.parm1 is 4000 characters. 
		// So the input is split into batch of 100s and pushed into the event. 
		for(var i = 0; i < Math.ceil(length/100); i++) {
			var startIndex = 100 * i;
			var endIndex = length - 1 > (startIndex + 99) ? (startIndex + 99) : length - 1;
			var tempList = certificateSysIdList.slice(startIndex, endIndex+1);
			var payload = {
				'certificate_ids': tempList,
				'opened_through': openedThrough,
				'trigger_id': triggerId
			};

			gs.eventQueue('sn_disco_certmgmt.renewal.initiated', null, JSON.stringify(payload), "");
		}
        return { "trigger_id": triggerId };
	},

    triggerRenewal: function(certificateSysId, certMeta, subjectCommonAttrs, openedThrough, triggerId) {
        var certGr = new GlideRecord("cmdb_ci_certificate");
        if (!certGr.get(certificateSysId)) {
            return {
                "certificate_sys_id": certificateSysId,
                "error": gs.getMessage("Certificate not found for the given certificate sys_id.")
            };
        }

        var taskGr = this.getRenewalTaskForCertificate(certificateSysId);
        if (!gs.nil(taskGr)) {
            return {
                "certificate_sys_id": certificateSysId,
                "renewal_task_id": taskGr.getValue("sys_id")
            };
        }
        var certMetadataGr = gs.nil(certMeta) ? this.getCertMetadataGr(certGr) : certMeta;
        if (certMetadataGr.getValue("auto_renewal_state") != "ready"
				&& certMetadataGr.getValue("auto_renewal_state") != "error") { // Allow retry when it is in error state
			var taskId = certMetadataGr.getValue("renew_certificate_task");
            if (!gs.nil(taskId)) {
				taskGr = new GlideRecord('sn_disco_certmgmt_renew_task');
				taskGr.get(taskId);
				if(taskGr.getValue('state') != 3) // Ignore tasks in failed state and allow retry
					return {
						"certificate_sys_id": certificateSysId,
						"renewal_task_id": certMetadataGr.getValue("renew_certificate_task")
					};
            } else {
				if (certMetadataGr.getValue("auto_renewal_state") == "processing") {
					return {
						"certificate_sys_id": certificateSysId,
						"error": gs.getMessage("Renewal already in progress!")
					};
				}
				return {
					"certificate_sys_id": certificateSysId,
					"error": gs.getMessage("Error while renewing certificate. Please try manually")
				};
			}
        }
        this.updateStateToProcessing(certMetadataGr);
        try {

            var certData = this.getParameterMap(certGr, subjectCommonAttrs);
            var renewalTaskId = this.createRenewTask(certGr, certData, certMetadataGr, openedThrough, triggerId);
            new GenerateCSRProbeInvoker().sendProbe(certData);
            this.updateStateToProcessed(certMetadataGr, renewalTaskId);
            return {
                "renewal_task_id": renewalTaskId,
                "certificate_sys_id": certificateSysId,
            };
        } catch (err) {
            this.updateStateToError(certMetadataGr);
            gs.error("CertificateRenewalTaskUtil | Failure while initiating renewal process for certificate " + certMetadataGr.certificate + " \n" + err);
			return {
                "certificate_sys_id": certificateSysId,
                "error": gs.getMessage("Error while renewing certificate. Please try manually")
            };
        }
    },

    getCertMetadataGr: function(certGr) {
        var certificateSysId = certGr.getValue("sys_id");
        var certMetadataGr = new GlideRecord("sn_disco_certmgmt_certificate_metadata");
        certMetadataGr.get("certificate", certificateSysId);
        if (gs.nil(certMetadataGr)) {
            certMetadataGr.initialize();
            certMetadataGr.setValue("auto_renewal_state", "ready");
            certMetadataGr.setValue("certificate", certificateSysId);
            certMetadataGr.setValue("auto_renew_days_before_expiry", 30);
            certMetadataGr.setValue("auto_renew_enabled", "false");
            certMetadataGr.insert();
        }
        return certMetadataGr;
    },

    getRenewalTaskForCertificate: function(certificateSysId) {
        var taskGr = new GlideRecord("sn_disco_certmgmt_renew_task");
        taskGr.addQuery("certificate", certificateSysId);
		taskGr.addQuery('state', 'NOT IN', [3]); // Exclude failed task and allow retry for failed tasks
        taskGr.query();
        if (taskGr.next())
            return taskGr;
        return null;
    },

    updateStateToProcessing: function(certMetadataGr) {
        certMetadataGr.setValue("auto_renewal_state", "processing");
        certMetadataGr.update();
    },

    updateStateToProcessed: function(certMetadataGr, renewalTaskId) {
        certMetadataGr.setValue("auto_renewal_state", "processed");
        certMetadataGr.setValue("renew_certificate_task", renewalTaskId);
        certMetadataGr.update();
    },

    updateStateToError: function(certMetadataGr) {
        certMetadataGr.setValue("auto_renewal_state", "error");
        certMetadataGr.update();
    },

    createRenewTask: function(certGr, certdata, certMetadataGr, openedThrough, triggerId) {
        var renewTaskgr = new GlideRecord('sn_disco_certmgmt_renew_task');
        renewTaskgr.initialize();
        renewTaskgr.setValue('sys_domain', certdata.sys_domain);
        renewTaskgr.setValue('subject_common_name', certdata.subject_common_name);
		var san = gs.nil(certdata.subject_alternative_name)
			? certdata.subject_common_name
			: certdata.subject_common_name + "," +certdata.subject_alternative_name;
        renewTaskgr.setValue('subject_alternative_name', san);
        renewTaskgr.setValue('organization', certdata.organization);
        renewTaskgr.setValue('organizational_unit', certdata.organization_unit);
        renewTaskgr.setValue('locality', certdata.locality);
        renewTaskgr.setValue('province', certdata.province);
        renewTaskgr.setValue('country', certdata.country);
        renewTaskgr.setValue('email', certdata.email);
        renewTaskgr.setValue('state', 1);
        renewTaskgr.setValue('certificate', certdata.certificate_sys_id);
        renewTaskgr.setValue('certificate_purpose', certdata.certificate_purpose);
        renewTaskgr.setValue('environment', certdata.environment);
        renewTaskgr.setValue('validity_period', certdata.validity_period);
		renewTaskgr.setValue('certificate_owner_group', certGr.getValue('assignment_group'));
		renewTaskgr.setValue('certificate_owner', certGr.getValue('assigned_to'));
		renewTaskgr.setValue('renewal_tracking', certGr.getValue('renewal_tracking'));
        renewTaskgr.setValue('active', true);
		renewTaskgr.setValue('opened_through', openedThrough);
		renewTaskgr.setValue('priority', 3);
		renewTaskgr.setValue('trigger_id', triggerId);

        if (!gs.nil(certMetadataGr)) {
            renewTaskgr.setValue("auto_renew_enabled", certMetadataGr.getValue("auto_renew_enabled"));
            renewTaskgr.setValue("auto_renew_days_before_expiry", certMetadataGr.getValue("auto_renew_days_before_expiry"));
        }
        var taskId = renewTaskgr.insert();
        new CertificateRequestAutomatedFlow().updateCertTaskWorkNotes(taskId, gs.getMessage('starting_auto_renewal_process'));

        certdata['renewal_task_id'] = taskId;
        return taskId;
    },
    getCertValiditySpan: function(certGr) {
        var validFrom = certGr.getValue('valid_from');
        var validTo = certGr.getValue('valid_to');

        var fromDate = new GlideDateTime(validFrom);
        var toDate = new GlideDateTime(validTo);

        var days = GlideDateTime.subtract(fromDate, toDate).getRoundedDayPart();
        return days;
    },
    getParameterMap: function(certGr, subjectCommonAttrs) {
        var parameterMap = {};
        parameterMap["certificate_sys_id"] = certGr.getValue("sys_id");
		var domain = gs.getSession().getCurrentDomainID();
        parameterMap["sys_domain"] = domain != null ? domain : certGr.getValue('sys_domain');

        parameterMap["subject_common_name"] = this.getAttributes("subject_common_name", subjectCommonAttrs, certGr);

        parameterMap["subject_alternative_name"] = this.getSAN("subject_alternative_name", subjectCommonAttrs, certGr);
        parameterMap["organization"] = this.getAttributes("subject_organization", subjectCommonAttrs, certGr);
        parameterMap["organization_unit"] = this.getAttributes("subject_organizational_unit", subjectCommonAttrs, certGr);
        parameterMap["locality"] = this.getAttributes("subject_locality", subjectCommonAttrs, certGr);
        parameterMap["province"] = this.getAttributes("subject_state", subjectCommonAttrs, certGr);
        parameterMap["country"] = this.getAttributes("subject_country", subjectCommonAttrs, certGr);
        parameterMap["email"] = this.getAttributes("subject_email", subjectCommonAttrs, certGr);
        parameterMap["certificate_purpose"] = this.getAttributes("service_type", subjectCommonAttrs, certGr);
        parameterMap["environment"] = this.getAttributes("environment", subjectCommonAttrs, certGr);
        parameterMap["validity_period"] = (subjectCommonAttrs && subjectCommonAttrs['validity_period']) || this.getCertValiditySpan(certGr);

        return parameterMap;
    },
    getAttributes: function(key, subjectCommonAttrs, certGr) {
        return (subjectCommonAttrs && subjectCommonAttrs[key]) || certGr.getValue(key);
    },

	getSAN: function(key, subjectCommonAttrs, certGr) {
		if (subjectCommonAttrs && subjectCommonAttrs[key]) {
			return subjectCommonAttrs[key];
		}
		var certDomainGr = new GlideRecord('certificate_domain');
		var sanIds = certGr.getValue('subject_alternative_name').split(',');
		certDomainGr.addQuery('sys_id', 'IN', sanIds);
		certDomainGr.query();
		var subjectAlternativeNames = [];
		while(certDomainGr.next()) {
			subjectAlternativeNames.push(certDomainGr.getValue('domain'));
		}
		subjectAlternativeNames.splice(subjectAlternativeNames.indexOf(certGr.getValue('subject_common_name')), 1);
		return subjectAlternativeNames.join(',');
	},

	deletePrivateKeys: function(privateKeyReferenceMap) {
		new GenerateCSRProbeInvoker().invokeDeletePrivateKeyProbe(privateKeyReferenceMap);
	},

    type: 'CertificateRenewalTaskUtil'
};
